        result = double(2)
        print(f"First test: double(2) = {result}")
        self.assertEqual(result, 4)

    def test_second(self):
        result = double(2)
        print(f"Second test: double(2) = {result}")
        self.assertEqual(result, 5)

if __name__ == '__main__':
    unittest.main()

